668			return opts, nil
669		}
670		if strings.TrimSpace(opts.Patch) != "" {
671			return opts, errors.New("pass either --patch or --patch-file, not both")
672		}
673		var (
674			data []byte
675			err  error
676		)
677		if patchFile == "-" {
678			data, err = io.ReadAll(stdin)
679		} else {
680			data, err = os.ReadFile(patchFile) //nolint:gosec // --patch-file is an explicit user-selected input path.
681		}
682		if err != nil {
683			return opts, fmt.Errorf("read patch file %q: %w", patchFile, err)
684		}
685		opts.Patch = string(data)
686		return opts, nil
