689	func buildTrailReviewCommentPatchRequest(opts trailReviewUpdateOptions) (api.TrailReviewCommentPatchRequest, error) {
690		var req api.TrailReviewCommentPatchRequest
691		if opts.BodyChanged {
692			body := strings.TrimSpace(opts.Body)
693			if body == "" {
694				return req, errors.New("finding body is required (pass --body)")
695			}
696			req.Body = stringPtr(body)
697		}
698		if opts.SeverityChanged {
699			severity := strings.ToLower(strings.TrimSpace(opts.Severity))
700			switch severity {
701			case trailReviewSeverityHigh, trailReviewSeverityMedium, trailReviewSeverityLow:
702				req.Severity = stringPtr(severity)
703			default:
704				return req, fmt.Errorf("invalid severity %q: valid values are high, medium, low", opts.Severity)
705			}
706		}
707		if opts.ConfidenceChanged {
708			if opts.Confidence < 0 || opts.Confidence > 1 {
709				return req, errors.New("--confidence must be between 0.0 and 1.0")
710			}
711			confidence := opts.Confidence
712			req.Confidence = &confidence
713		}
714		if !trailReviewCommentPatchHasFields(req) {
715			return req, errors.New("at least one finding field is required (pass --body, --severity, or --confidence)")
716		}
717		return req, nil
718	}
