792	func buildTrailReviewCommentLocation(opts trailReviewCommentAddOptions) (api.TrailReviewLocationCreateRequest, error) {
793		filePath := strings.TrimSpace(opts.FilePath)
794		line := opts.Line
795		if line < 0 || opts.StartLine < 0 || opts.EndLine < 0 {
796			return api.TrailReviewLocationCreateRequest{}, errors.New("line numbers must be non-negative")
797		}
798		if opts.StartLine > 0 {
799			if line > 0 {
800				return api.TrailReviewLocationCreateRequest{}, errors.New("pass either --line or --start-line, not both")
801			}
802			line = opts.StartLine
803		}
804		if filePath == "" && (line > 0 || opts.EndLine > 0) {
805			return api.TrailReviewLocationCreateRequest{}, errors.New("--line/--start-line/--end-line require --file")
806		}
807		if opts.EndLine > 0 && line == 0 {
808			return api.TrailReviewLocationCreateRequest{}, errors.New("--end-line requires --line or --start-line")
809		}
810		if opts.EndLine > 0 && opts.EndLine < line {
811			return api.TrailReviewLocationCreateRequest{}, errors.New("--end-line must be greater than or equal to the start line")
812		}
813	
814		loc := api.TrailReviewLocationCreateRequest{Granularity: "whole_change"}
815		if filePath == "" {
816			return loc, nil
817		}
818		loc.Granularity = "file"
819		loc.FilePath = stringPtr(filePath)
820		if line > 0 {
821			loc.Granularity = "line"
822			loc.StartLine = &line
823			if opts.EndLine > 0 {
824				loc.EndLine = &opts.EndLine
825				if opts.EndLine != line {
826					loc.Granularity = "range"
827				}
828			}
829		}
830		return loc, nil
831	}
