1209	func resolveGitRev(ctx context.Context, ref string) (string, error) {
1210		root, err := paths.WorktreeRoot(ctx)
1211		if err != nil {
1212			return "", fmt.Errorf("resolve worktree root: %w", err)
1213		}
1214		cmd := exec.CommandContext(ctx, "git", "-C", root, "rev-parse", ref)
1215		out, err := cmd.Output()
1216		if err != nil {
1217			return "", fmt.Errorf("git rev-parse %s: %w", ref, err)
1218		}
1219		sha := strings.TrimSpace(string(out))
1220		if sha == "" {
1221			return "", fmt.Errorf("git rev-parse %s: empty output", ref)
1222		}
1223		return sha, nil
1224	}
