1521	func truncateOneLine(s string, maxRunes int) string {
1522		s = strings.ReplaceAll(s, "\r\n", " ")
1523		s = strings.ReplaceAll(s, "\n", " ")
1524		s = strings.Join(strings.Fields(s), " ")
1525		runes := []rune(s)
1526		if len(runes) <= maxRunes {
1527			return s
1528		}
1529		return string(runes[:maxRunes]) + "…"
