97	func runTrailWatchResolved(cmd *cobra.Command, client *api.Client, trailID, description string, jsonOutput, showPings, once bool) error {
98		ctx := cmd.Context()
99		w := cmd.OutOrStdout()
100		errW := cmd.ErrOrStderr()
101		streamPath := reviewEventsPath(trailID)
102	
103		fmt.Fprintf(errW, "Watching %s — Ctrl+C to stop\n", description)
104	
105		backoff := reconnectBackoffInitial
106		lastEventID := ""
107	
108		for {
109			closeReason, lastSeenID, err := streamOnce(ctx, client, streamPath, lastEventID, jsonOutput, showPings, w, errW)
110			if lastSeenID != "" {
111				lastEventID = lastSeenID
112			}
113	
114			// Context cancelled (Ctrl+C) — exit cleanly.
115			if ctx.Err() != nil {
116				return nil //nolint:nilerr // ctx.Err() is the expected cancellation path; surface as clean exit
117			}
118	
119			if once {
120				switch closeReason {
121				case streamCloseTerminal:
122					return err
123				case streamCloseForbidden:
124					return NewSilentError(errors.New("stream access revoked"))
125				case streamCloseError:
126					if err == nil {
127						err = errors.New("stream error reported by server")
128					}
129					return NewSilentError(err)
130				case streamCloseTransport:
131					return err
132				case streamCloseReconnect, streamCloseDone:
133					return nil
134				}
135			}
136	
137			switch closeReason {
138			case streamCloseTerminal:
139				return err
140			case streamCloseDone:
141				return nil
142			case streamCloseForbidden:
143				return NewSilentError(errors.New("stream access revoked"))
144			case streamCloseReconnect:
145				// Clean server-initiated reconnect (max_duration). No backoff.
146				backoff = reconnectBackoffInitial
147				continue
148			case streamCloseError:
149				// Server emitted `event: error` — reconnect with backoff.
150				fmt.Fprintf(errW, "stream error reported by server, reconnecting in %s\n", backoff)
151			case streamCloseTransport:
152				// Network/transport error.
153				if err != nil {
154					fmt.Fprintf(errW, "stream disconnected (%v), reconnecting in %s\n", err, backoff)
155				}
156			}
157	
158			// Sleep with cancellation.
159			select {
160			case <-ctx.Done():
161				return nil
162			case <-time.After(backoff):
163			}
164			backoff *= 2
165			if backoff > reconnectBackoffCap {
166				backoff = reconnectBackoffCap
167			}
168		}
169	}
