226	type streamCloseReason int
227	
228	const (
229		streamCloseTransport streamCloseReason = iota // network/transport error
230		streamCloseReconnect                          // server `event: reconnect`
231		streamCloseForbidden                          // server `event: forbidden`
232		streamCloseError                              // server `event: error`
233		streamCloseDone                               // context cancellation
234		streamCloseTerminal                           // non-recoverable HTTP status (401/403/404/410)
235	)
236	
237	// terminalHTTPStatuses are HTTP response codes for which retrying the SSE
238	// stream cannot succeed: auth failures (401/403) and resource-not-found-style
239	// errors (404/410). 429 is intentionally *not* terminal — it's a transient
240	// rate-limit signal that should back off and retry.
241	var terminalHTTPStatuses = [...]int{
242		http.StatusUnauthorized, // 401
243		http.StatusForbidden,    // 403
244		http.StatusNotFound,     // 404
245		http.StatusGone,         // 410
246	}
247	
248	func isTerminalHTTPError(err error) bool {
249		for _, code := range terminalHTTPStatuses {
250			if api.IsHTTPErrorStatus(err, code) {
251				return true
252			}
253		}
254		return false
255	}
256	
257	// streamOnce opens a single SSE connection, prints events until it closes for
258	// any reason, and returns the close reason plus the last `id:` observed (so
259	// the caller can pass it as `Last-Event-ID` on reconnect).
260	//
261	//nolint:cyclop,gocognit // SSE framing parser is naturally branchy; splitting hurts readability
262	func streamOnce(
263		ctx context.Context,
264		client *api.Client,
265		path string,
266		lastEventID string,
267		jsonOutput, showPings bool,
268		w, errW io.Writer,
269	) (streamCloseReason, string, error) {
270		headers := http.Header{}
271		headers.Set("Accept", "text/event-stream")
272		headers.Set("Cache-Control", "no-cache")
273		if lastEventID != "" {
274			headers.Set("Last-Event-ID", lastEventID)
275		}
276	
277		resp, err := client.GetStream(ctx, path, headers)
278		if err != nil {
279			return streamCloseTransport, "", fmt.Errorf("open SSE stream: %w", err)
280		}
281		defer resp.Body.Close()
282	
283		if err := checkTrailResponse(resp); err != nil {
284			// Terminal: surface the error and don't reconnect. 429 deliberately
285			// falls through to streamCloseTransport so the caller backs off.
286			if isTerminalHTTPError(err) {
287				return streamCloseTerminal, "", err
288			}
289			return streamCloseTransport, "", err
290		}
291	
292		scanner := bufio.NewScanner(resp.Body)
293		// SSE frames can be larger than the default 64KiB scanner buffer when a
294		// review event carries long comment bodies; bump to 1 MiB to match the API's
295		// per-comment limits.
296		scanner.Buffer(make([]byte, 0, 64*1024), 1<<20)
297	
298		var (
299			eventName  string
300			dataLines  []string
301			eventID    string // id of the in-progress frame (reset on flush)
302			lastSeenID string // most recent SSE id from any frame that includes one
303		)
304	
305		flush := func() (streamCloseReason, bool) {
306			defer func() {
307				eventName = ""
308				dataLines = nil
309				eventID = ""
310			}()
311			if eventName == "" && len(dataLines) == 0 {
312				return streamCloseTransport, false
313			}
314			data := strings.Join(dataLines, "\n")
315			printSSEEvent(w, errW, eventName, data, jsonOutput)
316	
317			if eventID != "" {
318				lastSeenID = eventID
319			}
320	
321			switch eventName {
322			case sseEventReconnect:
323				return streamCloseReconnect, true
324			case sseEventForbidden:
325				return streamCloseForbidden, true
326			case sseEventError:
327				return streamCloseError, true
328			}
329			return streamCloseTransport, false
330		}
331	
332		for scanner.Scan() {
333			line := scanner.Text()
334	
335			// Blank line dispatches the event.
336			if line == "" {
337				if reason, done := flush(); done {
338					return reason, lastSeenID, nil
339				}
340				continue
341			}
342	
343			// Comment / keepalive line.
344			if strings.HasPrefix(line, ":") {
345				if showPings {
346					fmt.Fprintln(errW, "ping:", strings.TrimSpace(strings.TrimPrefix(line, ":")))
347				}
348				continue
349			}
350	
351			field, value, ok := strings.Cut(line, ":")
352			if !ok {
353				// Field-only line (no colon) — per spec the value is empty.
354				field = line
355				value = ""
356			}
357			// Per SSE spec: a single leading space after the colon is ignored.
358			value = strings.TrimPrefix(value, " ")
359	
360			switch field {
361			case "event":
362				eventName = value
363			case "data":
364				dataLines = append(dataLines, value)
365			case "id":
366				eventID = value
367			case "retry":
368				// Ignored — we manage backoff client-side.
369			}
370		}
371	
372		if err := scanner.Err(); err != nil {
373			// Context cancellation surfaces here as a wrapped "context canceled".
374			if errors.Is(err, context.Canceled) || ctx.Err() != nil {
375				return streamCloseDone, lastSeenID, nil
376			}
377			return streamCloseTransport, lastSeenID, fmt.Errorf("read SSE stream: %w", err)
378		}
379		return streamCloseTransport, lastSeenID, nil
380	}
381	
382	// printSSEEvent renders a single SSE event in either human-readable or
383	// json-line form. `data` may be empty (e.g. for the rare frame with only an
384	// `event:` line) — we still print something so the caller sees it.
385	func printSSEEvent(w, errW io.Writer, eventName, data string, jsonOutput bool) {
386		if jsonOutput {
387			// Emit a JSON envelope so consumers can reliably parse with
388			// `jq`/scripts. The data field is preserved verbatim if it isn't
389			// valid JSON; otherwise it's inlined as a sub-object.
390			envelope := map[string]any{"event": eventName}
391			if data != "" {
392				var sub any
393				if err := json.Unmarshal([]byte(data), &sub); err == nil {
394					envelope["data"] = sub
395				} else {
396					envelope["data"] = data
397				}
398			}
399			out, err := json.Marshal(envelope)
400			if err != nil {
401				fmt.Fprintf(errW, "failed to marshal event: %v\n", err)
402				return
403			}
404			fmt.Fprintln(w, string(out))
405			return
406		}
407	
408		switch eventName {
409		case sseEventReady:
410			printReadyEvent(w, data)
411			return
412		case sseEventReconnect:
413			fmt.Fprintln(errW, "↻ server requested reconnect")
414			return
415		case sseEventForbidden:
416			fmt.Fprintln(errW, "✖ stream access revoked")
417			return
418		case sseEventError:
419			printStreamError(errW, data)
420			return
421		}
422	
423		if ev, ok := parseReviewStreamEvent(eventName, data); ok {
424			printReviewStreamEvent(w, ev)
425			return
426		}
427	
428		// Fallback for unknown events or unparseable payloads: print raw.
429		fmt.Fprintf(w, "%s: %s\n", eventName, truncateForLog(data, 500))
430	}
431	
432	type reviewReadyPayload struct {
433		TrailID string `json:"trail_id"`
434		Cursor  int    `json:"cursor"`
435	}
436	
437	type reviewStreamEvent struct {
438		ID              any            `json:"id"`
439		TrailID         string         `json:"trail_id"`
440		ReviewSessionID *string        `json:"review_session_id"`
441		ActorID         string         `json:"actor_id"`
442		EventType       string         `json:"event_type"`
443		TargetType      string         `json:"target_type"`
444		TargetID        string         `json:"target_id"`
445		Payload         map[string]any `json:"payload"`
446		CreatedAt       time.Time      `json:"created_at"`
447	}
448	
449	func printReadyEvent(w io.Writer, data string) {
450		var p reviewReadyPayload
451		if err := json.Unmarshal([]byte(data), &p); err == nil {
452			parts := []string{"● connected"}
453			if p.TrailID != "" {
454				parts = append(parts, "to trail "+p.TrailID)
455			}
456			if p.Cursor > 0 {
457				parts = append(parts, fmt.Sprintf("after event %d", p.Cursor))
458			}
459			fmt.Fprintln(w, strings.Join(parts, " "))
460			return
461		}
462		fmt.Fprintf(w, "ready: %s\n", truncateForLog(data, 500))
463	}
464	
465	func printStreamError(errW io.Writer, data string) {
466		var p struct {
467			Message string `json:"message"`
468		}
469		if jerr := json.Unmarshal([]byte(data), &p); jerr != nil {
470			// Best-effort: server payload may be missing or malformed; we still
471			// want to surface that an error event arrived.
472			fmt.Fprintf(errW, "Warning: malformed error payload: %v\n", jerr)
473		}
474		if p.Message != "" {
475			fmt.Fprintf(errW, "✖ stream error: %s\n", p.Message)
476		} else {
477			fmt.Fprintln(errW, "✖ stream error")
478		}
479	}
480	
481	func parseReviewStreamEvent(eventName, data string) (reviewStreamEvent, bool) {
482		var ev reviewStreamEvent
483		if err := json.Unmarshal([]byte(data), &ev); err != nil {
484			return ev, false
485		}
486		if ev.EventType == "" {
487			ev.EventType = eventName
488		}
489		if ev.EventType == "" && ev.TargetType == "" && ev.TargetID == "" {
490			return ev, false
491		}
492		return ev, true
493	}
494	
495	func printReviewStreamEvent(w io.Writer, ev reviewStreamEvent) {
496		prefix := ""
497		if !ev.CreatedAt.IsZero() {
498			prefix = "[" + ev.CreatedAt.Local().Format("15:04:05") + "] "
499		}
500		actor := ev.ActorID
501		if actor == "" {
502			actor = "unknown actor"
503		}
504	
505		switch ev.EventType {
506		case "code_version.created":
507			fmt.Fprintf(w, "%scode version %s created (head %s)\n", prefix, ev.TargetID, payloadString(ev.Payload, "head_sha"))
508		case "code_version.base_sha_set":
509			fmt.Fprintf(w, "%scode version %s base set to %s\n", prefix, ev.TargetID, payloadString(ev.Payload, "base_sha"))
510		case "session.started":
511			fmt.Fprintf(w, "%ssession started by %s (code version %s)\n", prefix, actor, payloadString(ev.Payload, "code_version_id"))
512		case "session.ended":
513			reason := payloadString(ev.Payload, "reason")
514			if reason != "" {
515				fmt.Fprintf(w, "%ssession ended by %s (%s)\n", prefix, actor, reason)
516			} else {
517				fmt.Fprintf(w, "%ssession ended by %s\n", prefix, actor)
518			}
519		case "comment.created":
520			file := payloadString(ev.Payload, "file_path")
521			severity := payloadString(ev.Payload, "severity")
522			switch {
523			case file != "" && severity != "":
524				fmt.Fprintf(w, "%sfinding created by %s on %s (%s) — %s\n", prefix, actor, file, severity, ev.TargetID)
525			case file != "":
526				fmt.Fprintf(w, "%sfinding created by %s on %s — %s\n", prefix, actor, file, ev.TargetID)
527			default:
528				fmt.Fprintf(w, "%sfinding created by %s — %s\n", prefix, actor, ev.TargetID)
529			}
530		case "comment.status_changed":
531			fmt.Fprintf(w, "%sfinding %s status %s → %s\n", prefix, ev.TargetID, payloadString(ev.Payload, "from"), payloadString(ev.Payload, "to"))
532		case "comment.updated":
533			fmt.Fprintf(w, "%sfinding %s updated by %s\n", prefix, ev.TargetID, actor)
534		case "comment.stale_checked":
535			fmt.Fprintf(w, "%sfinding %s marked %s (%s)\n", prefix, ev.TargetID, payloadString(ev.Payload, "outcome"), payloadString(ev.Payload, "reason"))
536		case "suggested_change.created":
537			fmt.Fprintf(w, "%ssuggested change %s created for finding %s (%s)\n", prefix, ev.TargetID, payloadString(ev.Payload, "review_comment_id"), payloadString(ev.Payload, "change_type"))
538		case "suggested_change.updated":
539			fmt.Fprintf(w, "%ssuggested change %s updated by %s\n", prefix, ev.TargetID, actor)
540		case "suggested_change.check_result", "suggested_change.apply_result":
541			fmt.Fprintf(w, "%s%s for %s: %s\n", prefix, ev.EventType, payloadString(ev.Payload, "suggested_change_id"), payloadString(ev.Payload, "status"))
542		case "thread.created":
543			fmt.Fprintf(w, "%sthread %s created for finding %s\n", prefix, ev.TargetID, payloadString(ev.Payload, "review_comment_id"))
544		case "thread.message_added":
545			fmt.Fprintf(w, "%sthread message %s added by %s\n", prefix, ev.TargetID, actor)
546		case "thread.message_edited":
547			fmt.Fprintf(w, "%sthread message %s edited by %s\n", prefix, ev.TargetID, actor)
548		case "comment.linked":
549			fmt.Fprintf(w, "%sfinding link created: %s → %s\n", prefix, payloadString(ev.Payload, "source_comment_id"), payloadString(ev.Payload, "target_comment_id"))
550		case "comment.unlinked":
551			fmt.Fprintf(w, "%sfinding link removed: %s → %s\n", prefix, payloadString(ev.Payload, "source_comment_id"), payloadString(ev.Payload, "target_comment_id"))
552		default:
553			fmt.Fprintf(w, "%s%s %s/%s by %s\n", prefix, ev.EventType, ev.TargetType, ev.TargetID, actor)
554		}
555	}
556	
557	func payloadString(payload map[string]any, key string) string {
558		if payload == nil {
559			return ""
560		}
561		v, ok := payload[key]
562		if !ok || v == nil {
563			return ""
564		}
565		switch t := v.(type) {
566		case string:
567			return t
568		case fmt.Stringer:
569			return t.String()
570		default:
571			return fmt.Sprint(t)
572		}
573	}
574	
575	// truncateForLog clips body text on a rune boundary so a single multi-line
576	// payload doesn't blow up the watch view. Newlines collapse to spaces.
577	func truncateForLog(s string, maxRunes int) string {
578		s = strings.ReplaceAll(s, "\r\n", " ")
579		s = strings.ReplaceAll(s, "\n", " ")
580		rs := []rune(s)
581		if len(rs) <= maxRunes {
582			return s
583		}
584		return string(rs[:maxRunes]) + "…"
585	}
