1	package cli
2	
3	import (
4		"context"
5		"encoding/json"
6		"errors"
7		"fmt"
8		"io"
9		"os"
10		"path/filepath"
11		"strings"
12		"time"
13	
14		"github.com/entireio/cli/cmd/entire/cli/api"
15		"github.com/entireio/cli/cmd/entire/cli/auth"
16		"github.com/entireio/cli/cmd/entire/cli/gitremote"
17		"github.com/entireio/cli/cmd/entire/cli/jsonutil"
18		"github.com/entireio/cli/cmd/entire/cli/logging"
19		"github.com/entireio/cli/cmd/entire/cli/session"
20		"github.com/entireio/cli/cmd/entire/cli/settings"
21		"github.com/entireio/cli/cmd/entire/cli/validation"
22	)
23	
24	const (
25		trailEnablementCacheTTL                   = time.Hour
26		trailEnablementSessionStartRefreshTimeout = time.Second
27		trailEnablementRefreshTimeout             = 3 * time.Second
28	)
29	
30	type trailEnablementCacheStatus int
31	
32	const (
33		trailEnablementCacheUnknown trailEnablementCacheStatus = iota
34		trailEnablementCacheEnabled
35		trailEnablementCacheDisabled
36	)
37	
38	type trailEnablementScope struct {
39		Forge     string `json:"forge"`
40		Owner     string `json:"owner"`
41		Repo      string `json:"repo"`
42		RepoKey   string `json:"repo_key"`
43		APIBase   string `json:"api_base"`
44		AuthKey   string `json:"auth_key"`
45		Supported bool   `json:"supported"`
46	}
47	
48	// trailsEnabledForRepo reports cached enablement for the current repo.
49	func trailsEnabledForRepo(ctx context.Context) bool {
50		return cachedTrailsEnablementForRepo(ctx, time.Now()) == trailEnablementCacheEnabled
51	}
52	
53	func cachedTrailsEnablementForRepo(ctx context.Context, now time.Time) trailEnablementCacheStatus {
54		scope, err := currentTrailEnablementScope(ctx)
55		if err != nil {
56			return trailEnablementCacheUnknown
57		}
58		return cachedTrailsEnablementForScope(ctx, scope, now)
59	}
60	
61	func cachedTrailsEnablementForScope(ctx context.Context, scope trailEnablementScope, now time.Time) trailEnablementCacheStatus {
62		prefs, err := settings.LoadClonePreferences(ctx)
63		if err != nil || prefs.TrailsEnabled == nil || prefs.TrailsEnabledCheckedAt == nil {
64			return trailEnablementCacheUnknown
65		}
66		if !trailEnablementCacheMatchesScope(prefs, scope) || trailEnablementCacheExpired(*prefs.TrailsEnabledCheckedAt, now) {
67			return trailEnablementCacheUnknown
68		}
69		if *prefs.TrailsEnabled {
70			return trailEnablementCacheEnabled
71		}
72		return trailEnablementCacheDisabled
73	}
74	
75	func trailEnablementCacheMatchesScope(prefs *settings.ClonePreferences, scope trailEnablementScope) bool {
76		return prefs.TrailsEnabledRepoKey == scope.RepoKey &&
77			prefs.TrailsEnabledAPIBase == scope.APIBase &&
78			prefs.TrailsEnabledAuthKey == scope.AuthKey
79	}
80	
81	func trailEnablementCacheExpired(checkedAt time.Time, now time.Time) bool {
82		if checkedAt.IsZero() {
83			return true
84		}
85		if now.Before(checkedAt) {
86			return true
87		}
88		return now.Sub(checkedAt) > trailEnablementCacheTTL
89	}
90	
91	func currentTrailEnablementScope(ctx context.Context) (trailEnablementScope, error) {
92		rawURL, err := gitremote.GetRemoteURL(ctx, "origin")
93		if err != nil {
94			return trailEnablementScope{}, fmt.Errorf("get origin remote: %w", err)
95		}
96		if strings.TrimSpace(rawURL) == "" {
97			return trailEnablementScope{}, errors.New("get origin remote: empty URL")
98		}
99		info, err := gitremote.ParseURL(rawURL)
100		if err != nil {
101			return trailEnablementScope{}, fmt.Errorf("parse origin remote: %w", err)
102		}
103		authKey, err := auth.LocalIdentityCacheKey()
104		if err != nil {
105			return trailEnablementScope{}, fmt.Errorf("resolve auth cache key: %w", err)
106		}
107		return trailEnablementScope{
108			Forge:     info.Forge,
109			Owner:     info.Owner,
110			Repo:      info.Repo,
111			RepoKey:   trailEnablementRepoKey(info.Forge, info.Owner, info.Repo),
112			APIBase:   api.BaseURL(),
113			AuthKey:   authKey,
114			Supported: info.Forge != "",
115		}, nil
116	}
117	
118	func trailEnablementRepoKey(forge, owner, repo string) string {
119		return strings.Join([]string{forge, owner, repo}, "/")
120	}
121	
122	func saveTrailEnablementScopeHint(ctx context.Context, sessionID string, scope trailEnablementScope) error {
123		path, err := trailEnablementScopeHintPath(ctx, sessionID)
124		if err != nil {
125			return err
126		}
127		if err := os.MkdirAll(filepath.Dir(path), 0o750); err != nil {
128			return fmt.Errorf("create session state dir: %w", err)
129		}
130		data, err := jsonutil.MarshalIndentWithNewline(scope, "", "  ")
131		if err != nil {
132			return fmt.Errorf("marshal trail scope hint: %w", err)
133		}
134		if err := jsonutil.WriteFileAtomic(path, data, 0o600); err != nil {
135			return fmt.Errorf("write trail scope hint: %w", err)
136		}
137		return nil
138	}
139	
140	func loadTrailEnablementScopeHint(ctx context.Context, sessionID string) (trailEnablementScope, bool, error) {
141		path, err := trailEnablementScopeHintPath(ctx, sessionID)
142		if err != nil {
143			return trailEnablementScope{}, false, err
144		}
145		data, err := os.ReadFile(path) //nolint:gosec // path is derived from validated session ID
146		if err != nil {
147			if os.IsNotExist(err) {
148				return trailEnablementScope{}, false, nil
149			}
150			return trailEnablementScope{}, false, fmt.Errorf("read trail scope hint: %w", err)
151		}
152		var scope trailEnablementScope
153		if err := json.Unmarshal(data, &scope); err != nil {
154			return trailEnablementScope{}, false, fmt.Errorf("parse trail scope hint: %w", err)
155		}
156		return scope, true, nil
157	}
158	
159	func trailEnablementScopeHintPath(ctx context.Context, sessionID string) (string, error) {
160		if err := validation.ValidateSessionID(sessionID); err != nil {
161			return "", fmt.Errorf("invalid session ID: %w", err)
162		}
163		commonDir, err := session.GetGitCommonDir(ctx)
164		if err != nil {
